create or replace function public.publish_schoolpro_results(p_school uuid,p_term text,p_session text) returns integer language plpgsql security definer set search_path='' as $$declare n int;begin if not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role::text in('exam_officer','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;update public.schoolpro_results set status='published',published_at=now() where school_id=p_school and term=p_term and session=p_session and status='approved';get diagnostics n=row_count;return n;end$$;revoke all on function public.publish_schoolpro_results(uuid,text,text) from public,anon;grant execute on function public.publish_schoolpro_results(uuid,text,text) to authenticated;